function pickUp(){if(state.rod)return;state.rod=true;spareRod.visible=false;heldRod.visible=true;ui.interactionPrompt.classList.remove('show');ui.sceneCaption.textContent='Rod in hand. Find your angle and cast into the blue.';ui.castHint.classList.remove('hidden');toast('Fishing rod picked up. Hold SPACE to charge your cast.');tone(440,.1)}
function chooseFish(){const bait=baits.find(b=>b.id===state.selected),bonus=Math.min(state.level*.012,.15),weights=fishTypes.map(f=>f.base*(bait.modifier[f.id]||1)*(f.id==='tuna'?1+bonus:1)*(f.id==='shark'&&state.level<3?.55:1)),total=weights.reduce((a,b)=>a+b,0);let r=Math.random()*total;return fishTypes.find((f,i)=>{r-=weights[i];return r<=0})||fishTypes[0]}
function cast(){if(!state.rod){const d=boat.position.distanceTo(spareRod.position);if(d<4)pickUp();else toast('Walk over to the rod on the starboard side.');return}if(state.phase!=='ready')return;state.phase='waiting';state.waiting=0;state.waitDuration=5+Math.random()*9-state.charge*2.2;state.fish=null;state.charge=0;state.charging=false;setPhase('waiting');ui.sceneCaption.textContent='Your line is out. Watch the water for a bite.';tone(280,.16,.03)}
function startCharge(){if(state.phase!=='ready'||!state.rod)return;state.charging=true;state.charge=0;ui.powerMeter.classList.add('show')}
function endCharge(){if(!state.charging)return;state.charging=false;ui.powerMeter.classList.remove('show');cast()}
function recall(){if(state.phase!=='waiting')return;state.phase='ready';bobber.visible=line.visible=false;ui.sceneCaption.textContent='Nothing taking the bait. Try a new cast.';setPhase('ready')}
