 const rodPos=spareRod.getWorldPosition(new THREE.Vector3()),distance=camera.position.distanceTo(rodPos);if(!state.rod&&distance<3){ui.interactionPrompt.classList.add('show');ui.interactionPrompt.innerHTML='Press E or tap to pick up the fishing rod <span>WASD · DRAG TO LOOK</span>'}else if(!state.rod){ui.interactionPrompt.classList.remove('show');ui.interactionPrompt.innerHTML='Walk to the fishing rod <span>WASD · DRAG TO LOOK</span>'}
