input.newString:
function frame(){requestAnimationFrame(frame);const dt=Math.min(.05,clock.getDelta());update(dt)}
function hook(){if(state.phase!=='bite')return;state.phase='fight';state.progress=0;state.tension=42;state.overload=0;state.pull=0;ui.sceneCaption.textContent='Reel in the green zone. Ease off when the fish surges.';setPhase('fight');tone(590,.12,.035)}
function action(){if(state.phase==='ready'){if(!state.rod)pickUp();else cast()}else if(state.phase==='bite')hook();else if(state.phase==='waiting')recall()}
function setReeling(on){state.held=!!on&&state.phase==='fight';ui.reelButton.classList.toggle('pressed',state.held)}
function updateTouchAction(){if(!ui.touchAction)return;ui.touchAction.textContent=!state.rod?'PICK UP':state.phase==='bite'?'HOOK IT':state.phase==='waiting'?'RECALL':state.phase==='fight'?'REEL':'CAST'}
function look(dx,dy){state.yaw-=dx*.004;state.pitch=clamp(state.pitch-dy*.003,-1.15,.85)}
function closeOnEscape(e){if(e.key==='Escape'){closeUtilities();if(state.phase==='reveal')closeCatch()}}
canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;state.lookDrag=true;state.lastX=e.clientX;state.lastY=e.clientY;try{canvas.setPointerCapture(e.pointerId)}catch{}});
canvas.addEventListener('pointermove',e=>{if(!state.lookDrag)return;look(e.clientX-state.lastX,e.clientY-state.lastY);state.lastX=e.clientX;state.lastY=e.clientY});
const endLook=e=>{state.lookDrag=false;try{canvas.releasePointerCapture(e.pointerId)}catch{}};
canvas.addEventListener('pointerup',endLook);canvas.addEventListener('pointercancel',endLook);canvas.addEventListener('contextmenu',e=>e.preventDefault());
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();state.keys[e.code]=true;if(e.repeat)return;if(e.code==='KeyE'&&!state.rod)pickUp();if(e.code==='Space'){if(state.phase==='ready')startCharge();else if(state.phase==='fight')setReeling(true);else if(state.phase==='bite')hook()}if(e.code==='Escape')closeOnEscape(e)});
window.addEventListener('keyup',e=>{state.keys[e.code]=false;if(e.code==='Space'){if(state.charging)endCharge();setReeling(false)}});
window.addEventListener('blur',()=>{state.keys={};state.lookDrag=false;state.charging=false;setReeling(false);ui.powerMeter.classList.remove('show')});
ui.castButton.addEventListener('click',()=>{if(!state.rod)pickUp();else cast()});
ui.recallButton.addEventListener('click',recall);
ui.reelButton.addEventListener('pointerdown',e=>{e.preventDefault();setReeling(true);try{ui.reelButton.setPointerCapture(e.pointerId)}catch{}});
['pointerup','pointercancel','lostpointercapture'].forEach(type=>ui.reelButton.addEventListener(type,()=>setReeling(false)));
ui.touchAction.addEventListener('click',action);
ui.soundToggle.addEventListener('click',()=>{state.sound=!state.sound;ui.soundToggle.classList.toggle('active',state.sound);ui.soundToggle.setAttribute('aria-pressed',String(state.sound));if(state.sound)tone(620,.1)});
ui.shopOpen.addEventListener('click',shop);ui.bookOpen.addEventListener('click',book);
document.querySelectorAll('[data-close]').forEach(x=>x.addEventListener('click',closeUtilities));
ui.shopModal.addEventListener('click',e=>{if(e.target===ui.shopModal)closeUtilities()});ui.bookModal.addEventListener('click',e=>{if(e.target===ui.bookModal)closeUtilities()});
ui.keepButton.addEventListener('click',closeCatch);ui.modalClose.addEventListener('click',closeCatch);ui.catchModal.querySelector('.modal-backdrop').addEventListener('click',closeCatch);
const joy=ui.joystick,knob=ui.joystickKnob;let joyPointer=null;
function joystickMove(e){if(joyPointer!==e.pointerId)return;const r=joy.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=e.clientX-cx,dy=e.clientY-cy,max=r.width*.34,len=Math.hypot(dx,dy)||1,m=Math.min(max,len);state.moveX=dx/len*m/max;state.moveY=dy/len*m/max;knob.style.transform=`translate(${state.moveX*max}px, ${state.moveY*max}px)`}
joy.addEventListener('pointerdown',e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joystickMove(e)});joy.addEventListener('pointermove',joystickMove);
const releaseJoy=e=>{if(joyPointer!==e.pointerId)return;joyPointer=null;state.moveX=state.moveY=0;knob.style.transform='translate(0, 0)'};
joy.addEventListener('pointerup',releaseJoy);joy.addEventListener('pointercancel',releaseJoy);
ui.touchLook.addEventListener('pointerdown',e=>{e.preventDefault();state.lookDrag=true;state.lastX=e.clientX;state.lastY=e.clientY;ui.touchLook.setPointerCapture(e.pointerId)});
ui.touchLook.addEventListener('pointermove',e=>{if(!state.lookDrag||!ui.touchLook.hasPointerCapture(e.pointerId))return;look(e.clientX-state.lastX,e.clientY-state.lastY);state.lastX=e.clientX;state.lastY=e.clientY});
ui.touchLook.addEventListener('pointerup',()=>{state.lookDrag=false});ui.touchLook.addEventListener('pointercancel',()=>{state.lookDrag=false});
window.addEventListener('resize',resize);document.addEventListener('visibilitychange',()=>{if(document.hidden){state.held=false;state.charging=false}});
function initialize(){resize();makeBaits();updateStats();renderJournal();setPhase('ready');updateTouchAction();ui.interactionPrompt.innerHTML='Walk to the fishing rod <span>WASD · DRAG TO LOOK</span>';if(!('ontouchstart'in window)&&navigator.maxTouchPoints===0)ui.mobileControls.classList.add('desktop-hidden');frame()}
initialize();

