import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const cfg=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(process.env.RUNTIME_DIR,'scripts/display'),'utf8').trim();
const browser=await chromium.launch({...cfg.browser.launchOptions,timeout:30000});
const errors=[];
const wait=ms=>new Promise(r=>setTimeout(r,ms));
try {
 const page=await browser.newPage({viewport:{width:1100,height:760}});
 page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://localhost:8000',{waitUntil:'load'});
 await page.waitForFunction(()=>document.querySelector('#scene')?.width>0);
 await page.waitForTimeout(1200);
 await page.locator('#shopOpen').click();
 if(!await page.locator('#shopModal').isVisible()) throw new Error('Shop did not open');
 await page.locator('#shopContent [data-buy="bait"]').click();
 await page.locator('#bookOpen').click();
 if(!await page.locator('#bookModal').isVisible()) throw new Error('Collection book did not open');
 await page.locator('#bookModal [data-close]').click();
 await page.keyboard.down('w'); await page.keyboard.down('d'); await wait(800); await page.keyboard.up('w'); await page.keyboard.up('d');
 await page.keyboard.press('e');
 await page.waitForFunction(()=>document.querySelector('#castHint').classList.contains('hidden')===false,{timeout:5000});
 console.log('Desktop rod pickup: ok');
 let caught=false;
 for(let attempt=0;attempt<3&&!caught;attempt++) {
   await page.locator('#castButton').hover(); await page.mouse.down(); await wait(1000); await page.mouse.up();
   await page.waitForFunction(()=>!document.querySelector('#waitingState').classList.contains('hidden')||document.querySelector('#biteAlert').classList.contains('show'),{timeout:5000}).catch(()=>{});
   await page.waitForFunction(()=>document.querySelector('#biteAlert').classList.contains('show'),{timeout:15000});
   await page.keyboard.press('Space');
   for(let i=0;i<80;i++) {
     if(await page.locator('#catchModal').isVisible()) {caught=true;break;}
     if(await page.locator('#castReady').isVisible()) break;
     await page.keyboard.down('Space'); await wait(260); await page.keyboard.up('Space'); await wait(400);
   }
   if(await page.locator('#catchModal').isVisible()) caught=true;
   if(!caught && attempt<2) console.log('Fish escaped; retrying');
 }
 if(!caught) throw new Error('Could not complete a fish fight');
 console.log('Desktop charged cast, bite, hook, reel, catch: ok ('+(await page.locator('#catchTitle').textContent())+')');
 await page.locator('#keepButton').click();
