import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime=join(process.env.HOME,'.local/share/omgithub-playwright');
const require=createRequire(join(runtime,'package.json'));
const {chromium}=require('playwright');
const cfg=JSON.parse(readFileSync(join(runtime,'linux.json'),'utf8'));
if(process.platform==='linux') process.env.DISPLAY ||= ':'+readFileSync(join(runtime,'display'),'utf8').trim();
const browser=await chromium.launch({...cfg.browser.launchOptions,timeout:30000});
try {
 const page=await browser.newPage({viewport:{width:1100,height:760}});
 await page.addInitScript(()=>{Math.random=()=>0.1;localStorage.clear()});
 await page.goto('http://localhost:8000',{waitUntil:'load'}); await page.waitForTimeout(1000);
 await page.keyboard.down('w'); await page.keyboard.down('d'); await page.waitForTimeout(800); await page.keyboard.up('w'); await page.keyboard.up('d'); await page.keyboard.press('e');
 await page.waitForFunction(()=>!document.querySelector('#castHint').classList.contains('hidden'));
 await page.locator('#castButton').hover(); await page.mouse.down(); await page.waitForTimeout(1000); await page.mouse.up();
 await page.waitForFunction(()=>document.querySelector('#biteAlert').classList.contains('show'),null,{timeout:15000}); await page.keyboard.press('Space');
 for(let i=0;i<20;i++) {await page.keyboard.down('Space');await page.waitForTimeout(700);await page.keyboard.up('Space');await page.waitForTimeout(700); console.log(i,await page.locator('#tensionValue').innerText(),await page.locator('#sceneCaption').innerText(),await page.locator('#catchModal').isVisible()); if(await page.locator('#catchModal').isVisible())break;}
} finally {await browser.close()}

